<?php
require_once __DIR__.'/../includes/bootstrap.php';$workspace=require_permission('view');$st=$GLOBALS['pdo']->prepare('SELECT s.*,u.name owner_name,(SELECT d.id FROM datasets d WHERE d.source_id=s.id ORDER BY d.id LIMIT 1) dataset_id FROM data_sources s JOIN users u ON u.id=s.owner_id WHERE s.workspace_id=? ORDER BY s.created_at DESC');$st->execute([$workspace['id']]);$sources=$st->fetchAll();require_once __DIR__.'/../includes/header.php';$layout='app';datanix_header('Data sources','sources',$layout);
?>
